import numpy as np
import pandas as pd

MODEL_ID = "CR-PD-001"
TARGET = "default_flag"
NUMERIC_VARS = ['duration', 'amount', 'age']
# First level of each list is the reference category (dropped from the design matrix).
FACTOR_LEVELS = {
    'status': ['no checking account', '... < 0 DM', '0<= ... < 200 DM', '... >= 200 DM / salary for at least 1 year'],
    'credit_history': ['no credits taken/all credits paid back duly', 'all credits at this bank paid back duly', 'existing credits paid back duly till now', 'delay in paying off in the past', 'critical account/other credits elsewhere'],
    'savings': ['unknown/no savings account', '... <  100 DM', '100 <= ... <  500 DM', '500 <= ... < 1000 DM', '... >= 1000 DM'],
}


class RedevelopedLogit:
    def __init__(self):
        self.coef_ = None
        self.std_err_ = None
        self.n_iter_ = None

    @staticmethod
    def design_matrix(df: pd.DataFrame) -> pd.DataFrame:
        cols = {"(Intercept)": np.ones(len(df))}
        for v in NUMERIC_VARS:
            cols[v] = df[v].astype(float).to_numpy()
        for v, levels in FACTOR_LEVELS.items():
            values = df[v].astype(str)
            unknown = set(values) - set(levels)
            if unknown:
                raise ValueError(f"Unseen levels for {v}: {sorted(unknown)}")
            for level in levels[1:]:
                cols[f"{v}{level}"] = (values == level).astype(float).to_numpy()
        return pd.DataFrame(cols, index=df.index)

    def fit(self, df: pd.DataFrame, max_iter: int = 100, tol: float = 1e-12):
        X = self.design_matrix(df)
        Xv, y = X.to_numpy(), df[TARGET].to_numpy(dtype=float)
        beta = np.zeros(Xv.shape[1])
        for i in range(1, max_iter + 1):
            p = 1.0 / (1.0 + np.exp(-(Xv @ beta)))
            hessian = Xv.T @ (Xv * (p * (1 - p))[:, None])
            step = np.linalg.solve(hessian, Xv.T @ (y - p))
            beta = beta + step
            if np.max(np.abs(step)) < tol:
                break
        p = 1.0 / (1.0 + np.exp(-(Xv @ beta)))
        hessian = Xv.T @ (Xv * (p * (1 - p))[:, None])
        self.coef_ = pd.Series(beta, index=X.columns)
        self.std_err_ = pd.Series(np.sqrt(np.diag(np.linalg.inv(hessian))), index=X.columns)
        self.n_iter_ = i
        return self

    def predict_proba(self, df: pd.DataFrame) -> np.ndarray:
        X = self.design_matrix(df)[self.coef_.index]
        return 1.0 / (1.0 + np.exp(-(X.to_numpy() @ self.coef_.to_numpy())))

    def coefficients(self) -> pd.DataFrame:
        return pd.DataFrame({"term": self.coef_.index, "estimate": self.coef_.values,
                             "std_error": self.std_err_.values})

    @classmethod
    def from_coefficients(cls, table: pd.DataFrame) -> "RedevelopedLogit":
        m = cls()
        m.coef_ = pd.Series(table["estimate"].to_numpy(), index=table["term"].to_list())
        if "std_error" in table:
            m.std_err_ = pd.Series(table["std_error"].to_numpy(), index=table["term"].to_list())
        return m
